const App: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [currentView, setCurrentView] = useState('home');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isSearchOpen, setIsSearchOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleNavigate = (view: string, id?: string) => {
    setCurrentView(view);
    setSelectedId(id || null);
    window.scrollTo(0, 0);
  };

  const renderContent = () => {
    switch (currentView) {
      case 'news-list':
        return <NewsListPage onBack={() => setCurrentView('home')} onSelect={(id) => handleNavigate('news-detail', id)} />;
      case 'news-detail':
        return <NewsDetailPage id={selectedId || ''} onBack={() => setCurrentView('news-list')} onNavigate={handleNavigate} />;
      case 'service-detail':
        return <ServiceDetailPage id={selectedId || ''} onBack={() => setCurrentView('home')} />;
      case 'about-page':
        return <PageLayout title="About Us" subtitle="熱狂を日常に、ワクワクを未来に。" onBack={() => setCurrentView('home')}><About /></PageLayout>;
      case 'contact-page':
        return <PageLayout title="Contact" subtitle="プロジェクトのご相談はこちらから" onBack={() => setCurrentView('home')}><Contact /></PageLayout>;
      case 'services-list':
        return <PageLayout title="Services" subtitle="スポーツ・エンタメDXへの挑戦" onBack={() => setCurrentView('home')}><Services onSelect={(id) => handleNavigate('service-detail', id)} /></PageLayout>;
      case 'portfolio-list':
        return <PageLayout title="Portfolio" subtitle="これまでの主な実績" onBack={() => setCurrentView('home')}><Portfolio /></PageLayout>;
      case 'sitemap':
        return <SitemapPage onBack={() => setCurrentView('home')} onNavigate={handleNavigate} />;
      case 'privacy-policy':
        return <LegalPage title="Privacy Policy" content="ここにプライバシーポリシーの内容が入ります。" onBack={() => setCurrentView('home')} />;
      case 'terms-of-service':
        return <LegalPage title="Terms of Service" content="ここにサイト利用規約の内容が入ります。" onBack={() => setCurrentView('home')} />;
      case 'cookie-policy':
        return <LegalPage title="Cookie Policy" content="ここにクッキーポリシーの内容が入ります。" onBack={() => setCurrentView('home')} />;
      default:
        return (
          <main className="animate-in fade-in duration-1000">
            <section id="hero">
              <Hero />
            </section>

            <section id="news" className="py-24 bg-white">
              <News 
                onViewAll={() => handleNavigate('news-list')} 
                onSelect={(id) => handleNavigate('news-detail', id)} 
              />
            </section>

            <section id="services" className="py-32 bg-slate-50">
              <Services onSelect={(id) => handleNavigate('service-detail', id)} />
            </section>

            <section id="portfolio" className="py-32 bg-white">
              <Portfolio onViewAll={() => handleNavigate('portfolio-list')} />
            </section>

            <section id="about" className="py-32 bg-slate-50">
              <About />
            </section>

            <section id="contact" className="py-32 bg-slate-900 text-white">
              <Contact />
            </section>
          </main>
        );
    }
  };

  return (
    <div className="relative min-h-screen">
      <Navbar 
        isScrolled={isScrolled} 
        onNavigate={handleNavigate} 
        onSearchToggle={() => setIsSearchOpen(true)}
      />

      {renderContent()}

      <Footer onNavigate={handleNavigate} />

      <CookieBanner onNavigate={handleNavigate} />

      {isSearchOpen && (
        <SearchModal 
          onClose={() => setIsSearchOpen(false)} 
          onNavigate={(view, id) => {
            setIsSearchOpen(false);
            handleNavigate(view === 'detail' ? 'service-detail' : view, id);
          }}
        />
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

const SYSTEM_INSTRUCTION = `
あなたは山坂ホライゾン（Yamasaka Horizon）の「AIサイトナビゲーター」です。
ユーザーが入力したキーワードや悩みから、サイト内の最適な情報（サービス、実績、ニュース等）を提案するのが役割です。

あなたのトーン:
- 的確で、信頼感のあるプロフェッショナルな案内。
- 「推し活」や「エンタメDX」への高い専門性を感じさせる口調。

提案の指針:
1. ユーザーの問いに対し、山坂ホライゾンのどのページを見るべきか明確に提示してください。
2. 提案するリンク先（Services, Portfolio, News, Contact等）とその理由を簡潔に説明してください。
3. 最後に「検索バーを閉じて、該当セクションへ進むことをお勧めします」といった行動を促してください。

サイト構成の要約:
- Marketing Support: ファンの熱量を最大化する戦略。
- DX Support: テクノロジー（アプリ、スタジアム）の導入。
- Seminar & Education: 業界人材の育成。
- Portfolio: これまでの具体的な成功事例。
- Contact: プロジェクトの相談。
`;

export class GeminiService {
  async chat(history: { role: 'user' | 'model', parts: { text: string }[] }[], prompt: string) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [...history, { role: 'user', parts: [{ text: prompt }] }],
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
          temperature: 0.7,
        },
      });

      return response.text || "申し訳ありません。案内の生成中にエラーが発生しました。";
    } catch (error) {
      console.error("Gemini API Error:", error);
      return "エラーが発生しました。直接メニューから各ページをご覧いただくか、お問い合わせください。";
    }
  }
}

export const geminiService = new GeminiService();

import React, { useState, useMemo } from 'react';
import { siteContent } from '../siteContent';
import { geminiService } from '../services/geminiService';

interface SearchModalProps {
  onClose: () => void;
  onNavigate: (view: string, title?: string) => void;
}

export const SearchModal: React.FC<SearchModalProps> = ({ onClose, onNavigate }) => {
  const [query, setQuery] = useState('');
  const [aiResponse, setAiResponse] = useState<string | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);

  const results = useMemo(() => {
    if (!query.trim()) return [];

    const q = query.toLowerCase();
    const matches: { title: string, category: string, view: string, extra?: string }[] = [];

    // Search News
    siteContent.news.forEach(item => {
      if (item.title.toLowerCase().includes(q)) {
        matches.push({ title: item.title, category: 'NEWS', view: 'news-list' });
      }
    });

    // Search Services
    siteContent.services.forEach(item => {
      if (item.title.toLowerCase().includes(q) || item.jpTitle.toLowerCase().includes(q) || item.description.toLowerCase().includes(q)) {
        matches.push({ title: item.title, category: 'SERVICE', view: 'detail', extra: item.title });
      }
    });

    // Search Portfolio
    siteContent.portfolio.forEach(item => {
      if (item.title.toLowerCase().includes(q) || item.jpTitle.toLowerCase().includes(q) || item.description.toLowerCase().includes(q)) {
        matches.push({ title: item.title, category: 'PORTFOLIO', view: 'detail', extra: item.title });
      }
    });

    // About match
    if (siteContent.about.title.toLowerCase().includes(q) || siteContent.about.description1.toLowerCase().includes(q)) {
      matches.push({ title: 'About Us', category: 'ABOUT', view: 'about-page' });
    }

    return matches;
  }, [query]);

  const handleAiConsult = async () => {
    if (!query.trim() || isAiLoading) return;
    setIsAiLoading(true);
    setAiResponse(null);

    const response = await geminiService.chat([], `「${query}」について、サイト内のどこを見るべきか教えてください。`);
    setAiResponse(response);
    setIsAiLoading(false);
  };

  return (
    <div className="fixed inset-0 z-[110] flex items-start justify-center pt-[10vh] px-6">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={onClose}></div>

      <div className="relative w-full max-w-2xl bg-white rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
        <div className="p-6 border-b border-slate-100 flex items-center">
          <svg className="w-5 h-5 text-slate-400 mr-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
          <input 
            autoFocus
            type="text"
            placeholder="サイト内を検索... または悩みを入力"
            className="flex-1 bg-transparent border-none outline-none text-lg text-slate-800 placeholder-slate-300"
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              setAiResponse(null);
            }}
          />
          <button onClick={onClose} className="p-2 hover:bg-slate-50 rounded-full text-slate-400">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="max-h-[60vh] overflow-y-auto p-4">
          {query && results.length === 0 && !aiResponse && !isAiLoading && (
            <div className="py-12 text-center">
              <p className="text-slate-400 mb-6">「{query}」に一致する直接の結果は見つかりませんでした。</p>
              <button 
                onClick={handleAiConsult}
                className="px-6 py-3 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-full text-sm font-bold shadow-lg hover:scale-105 transition-transform flex items-center mx-auto"
              >
                <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.989-2.386l-.548-.547z" />
                </svg>
                AIに最適な案内を相談する
              </button>
